<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Billiards</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  background: #1a1a2e;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  font-family: Arial, sans-serif;
  color: #fff;
}
#instructions {
  margin: 10px 0;
  padding: 10px 20px;
  background: rgba(0,0,0,0.5);
  border-radius: 8px;
  font-size: 14px;
  text-align: center;
  max-width: 820px;
}
#instructions strong { color: #ffd700; }
canvas {
  border: 4px solid #4a2810;
  border-radius: 4px;
  cursor: crosshair;
  box-shadow: 0 0 30px rgba(0,0,0,0.8);
}
#controls {
  margin: 10px 0;
}
#controls button {
  padding: 10px 24px;
  font-size: 16px;
  background: #2d6b2d;
  color: #fff;
  border: 2px solid #4a9e4a;
  border-radius: 6px;
  cursor: pointer;
  margin: 0 5px;
}
#controls button:hover {
  background: #3a8a3a;
}
#status {
  margin: 5px 0;
  font-size: 13px;
  color: #aaa;
}
</style>
</head>
<body>
<div id="instructions">
  <strong>How to play:</strong> Click and hold on the <strong>white cue ball</strong>,
  then drag <strong>backward</strong> (away from your target) to aim and set power.
  The further you drag, the harder the shot. Release to strike!
  Pocket all the balls. Press <strong>Reset</strong> to re-rack.
</div>
<canvas id="canvas"></canvas>
<div id="controls">
  <button id="resetBtn">Reset / Rack</button>
</div>
<div id="status"></div>

<script>
(function() {
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');

  // Table dimensions
  const W = 800;
  const H = 400;
  const R = 11;
  const POCKET_R = 20;
  const RAIL = 30;

  canvas.width = W + RAIL * 2;
  canvas.height = H + RAIL * 2;

  // Pocket positions (relative to playfield 0,0 to W,H)
  const pockets = [
    { x: 2, y: 2 },
    { x: W / 2, y: -2 },
    { x: W - 2, y: 2 },
    { x: 2, y: H - 2 },
    { x: W / 2, y: H + 2 },
    { x: W - 2, y: H - 2 }
  ];

  // Ball colors
  const ballColors = [
    '#ffffff', // 0: cue
    '#f5d442', // 1: yellow
    '#2255cc', // 2: blue
    '#cc2222', // 3: red
    '#6622aa', // 4: purple
    '#ee7722', // 5: orange
    '#228833', // 6: green
    '#882222', // 7: maroon
    '#111111', // 8: black
    '#f5d442', // 9: yellow stripe
    '#2255cc', // 10: blue stripe
    '#cc2222', // 11: red stripe
    '#6622aa', // 12: purple stripe
    '#ee7722', // 13: orange stripe
    '#228833', // 14: green stripe
    '#882222'  // 15: maroon stripe
  ];

  // Physics constants
  const FRICTION = 0.4; // deceleration in px/s^2 per unit speed (coefficient)
  const FRICTION_DECEL = 60; // constant deceleration px/s^2
  const MIN_SPEED = 2; // below this, stop
  const RESTITUTION = 0.96; // cushion restitution
  const BALL_RESTITUTION = 0.98; // ball-ball restitution
  const MAX_POWER = 1800; // max shot speed px/s
  const MAX_DRAG = 200; // max drag distance in pixels for full power

  // State
  let balls = [];
  let paused = false;
  let animId = null;
  let lastTime = 0;

  // Aiming state
  let aiming = false;
  let aimStart = { x: 0, y: 0 };
  let aimCurrent = { x: 0, y: 0 };
  let cueBallIndex = -1;

  function getCueBall() {
    for (let i = 0; i < balls.length; i++) {
      if (balls[i].cue) return balls[i];
    }
    return null;
  }

  function createDefaultBalls() {
    const result = [];
    // Cue ball
    result.push({ x: W * 0.25, y: H / 2, vx: 0, vy: 0, cue: true });

    // Rack position (triangle at 3/4 of table)
    const rackX = W * 0.72;
    const rackY = H / 2;
    const spacing = R * 2.05;

    // Standard 8-ball rack order (simplified)
    const rackOrder = [1, 2, 3, 8, 4, 5, 6, 7, 9, 10, 11, 12, 13, 14, 15];
    let idx = 0;

    for (let row = 0; row < 5; row++) {
      for (let col = 0; col <= row; col++) {
        const bx = rackX + row * spacing * Math.cos(Math.PI / 6);
        const by = rackY + (col - row / 2) * spacing;
        const num = rackOrder[idx];
        result.push({
          x: bx,
          y: by,
          vx: 0,
          vy: 0,
          cue: false,
          number: num
        });
        idx++;
      }
    }

    return result;
  }

  // Sim API
  const sim = {
    W: W,
    H: H,
    R: R,

    reset: function(ballData) {
      balls = [];
      cueBallIndex = -1;
      for (let i = 0; i < ballData.length; i++) {
        const b = ballData[i];
        const ball = {
          x: b.x,
          y: b.y,
          vx: b.vx || 0,
          vy: b.vy || 0,
          cue: !!b.cue,
          potted: false,
          number: b.number !== undefined ? b.number : (i === 0 ? 0 : i)
        };
        balls.push(ball);
        if (ball.cue) cueBallIndex = i;
      }
    },

    step: function(dt) {
      if (dt <= 0) return;
      if (dt > 0.05) dt = 0.05; // cap for stability

      const substeps = 4;
      const subDt = dt / substeps;

      for (let s = 0; s < substeps; s++) {
        physicsStep(subDt);
      }

      draw();
    },

    state: function() {
      return balls.map(b => ({
        x: b.x,
        y: b.y,
        vx: b.vx,
        vy: b.vy,
        potted: b.potted,
        cue: b.cue
      }));
    },

    shoot: function(vx, vy) {
      const cue = getCueBall();
      if (cue && !cue.potted) {
        cue.vx = vx;
        cue.vy = vy;
      }
    },

    pause: function() {
      paused = true;
      if (animId) {
        cancelAnimationFrame(animId);
        animId = null;
      }
    },

    resume: function() {
      if (!paused) return;
      paused = false;
      lastTime = performance.now();
      animId = requestAnimationFrame(gameLoop);
    }
  };

  window.sim = sim;

  function physicsStep(dt) {
    // Update positions and apply friction
    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];
      if (b.potted) continue;

      // Apply friction (deceleration)
      const speed = Math.sqrt(b.vx * b.vx + b.vy * b.vy);
      if (speed > MIN_SPEED) {
        const frictionForce = FRICTION_DECEL + speed * FRICTION;
        const decel = frictionForce * dt;
        const newSpeed = Math.max(0, speed - decel);
        const ratio = newSpeed / speed;
        b.vx *= ratio;
        b.vy *= ratio;
      } else if (speed > 0) {
        b.vx = 0;
        b.vy = 0;
      }

      // Move
      b.x += b.vx * dt;
      b.y += b.vy * dt;
    }

    // Ball-to-ball collisions
    for (let i = 0; i < balls.length; i++) {
      if (balls[i].potted) continue;
      for (let j = i + 1; j < balls.length; j++) {
        if (balls[j].potted) continue;
        resolveBallCollision(balls[i], balls[j]);
      }
    }

    // Wall collisions
    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];
      if (b.potted) continue;
      resolveWallCollision(b);
    }

    // Pocket detection
    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];
      if (b.potted) continue;
      for (let p = 0; p < pockets.length; p++) {
        const dx = b.x - pockets[p].x;
        const dy = b.y - pockets[p].y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < POCKET_R) {
          b.potted = true;
          b.vx = 0;
          b.vy = 0;
          break;
        }
      }
    }
  }

  function resolveBallCollision(a, b) {
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const dist = Math.sqrt(dx * dx + dy * dy);
    const minDist = R * 2;

    if (dist < minDist && dist > 0.001) {
      // Normal vector
      const nx = dx / dist;
      const ny = dy / dist;

      // Separate balls
      const overlap = minDist - dist;
      a.x -= nx * overlap / 2;
      a.y -= ny * overlap / 2;
      b.x += nx * overlap / 2;
      b.y += ny * overlap / 2;

      // Relative velocity along normal
      const dvx = a.vx - b.vx;
      const dvy = a.vy - b.vy;
      const dvn = dvx * nx + dvy * ny;

      // Only resolve if approaching
      if (dvn > 0) {
        // Equal mass elastic collision with restitution
        const impulse = dvn * (1 + BALL_RESTITUTION) / 2;
        a.vx -= impulse * nx;
        a.vy -= impulse * ny;
        b.vx += impulse * nx;
        b.vy += impulse * ny;
      }
    }
  }

  function resolveWallCollision(b) {
    // Check if near a pocket - if so, don't bounce (let it fall in)
    for (let p = 0; p < pockets.length; p++) {
      const dx = b.x - pockets[p].x;
      const dy = b.y - pockets[p].y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < POCKET_R + R) return; // near pocket, skip wall collision
    }

    if (b.x < R) {
      b.x = R;
      b.vx = Math.abs(b.vx) * RESTITUTION;
    } else if (b.x > W - R) {
      b.x = W - R;
      b.vx = -Math.abs(b.vx) * RESTITUTION;
    }

    if (b.y < R) {
      b.y = R;
      b.vy = Math.abs(b.vy) * RESTITUTION;
    } else if (b.y > H - R) {
      b.y = H - R;
      b.vy = -Math.abs(b.vy) * RESTITUTION;
    }
  }

  // Drawing
  function draw() {
    const cw = canvas.width;
    const ch = canvas.height;

    // Clear
    ctx.fillStyle = '#2a1506';
    ctx.fillRect(0, 0, cw, ch);

    // Draw rails (wood border)
    ctx.fillStyle = '#5c3317';
    ctx.fillRect(0, 0, cw, ch);

    // Inner rail edge highlight
    ctx.fillStyle = '#3d7a3d';
    ctx.fillRect(RAIL - 4, RAIL - 4, W + 8, H + 8);

    // Felt
    ctx.fillStyle = '#1a7a3a';
    ctx.fillRect(RAIL, RAIL, W, H);

    // Felt texture (subtle)
    ctx.fillStyle = 'rgba(0,0,0,0.03)';
    for (let i = 0; i < W; i += 4) {
      ctx.fillRect(RAIL + i, RAIL, 1, H);
    }

    // Draw cushion edges
    ctx.strokeStyle = '#0f5a25';
    ctx.lineWidth = 3;
    ctx.strokeRect(RAIL + 1, RAIL + 1, W - 2, H - 2);

    // Draw pockets
    for (let p = 0; p < pockets.length; p++) {
      const px = pockets[p].x + RAIL;
      const py = pockets[p].y + RAIL;
      ctx.beginPath();
      ctx.arc(px, py, POCKET_R, 0, Math.PI * 2);
      ctx.fillStyle = '#111';
      ctx.fill();
      ctx.beginPath();
      ctx.arc(px, py, POCKET_R - 2, 0, Math.PI * 2);
      ctx.fillStyle = '#1a1a1a';
      ctx.fill();
    }

    // Draw head string line (faint)
    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
    ctx.lineWidth = 1;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(RAIL + W * 0.25, RAIL);
    ctx.lineTo(RAIL + W * 0.25, RAIL + H);
    ctx.stroke();
    ctx.setLineDash([]);

    // Draw balls
    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];
      if (b.potted) continue;
      drawBall(b, i);
    }

    // Draw aim line
    if (aiming) {
      const cue = getCueBall();
      if (cue && !cue.potted) {
        const dx = aimStart.x - aimCurrent.x;
        const dy = aimStart.y - aimCurrent.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist > 5) {
          const nx = dx / dist;
          const ny = dy / dist;

          // Aim line (forward direction)
          const lineLen = Math.min(dist * 2, 300);
          ctx.strokeStyle = 'rgba(255,255,255,0.7)';
          ctx.lineWidth = 2;
          ctx.setLineDash([8, 6]);
          ctx.beginPath();
          ctx.moveTo(cue.x + RAIL, cue.y + RAIL);
          ctx.lineTo(cue.x + RAIL + nx * lineLen, cue.y + RAIL + ny * lineLen);
          ctx.stroke();
          ctx.setLineDash([]);

          // Power indicator (cue stick behind)
          const power = Math.min(dist / MAX_DRAG, 1);
          const stickLen = 150;
          const stickStart = 15 + power * 40;
          ctx.strokeStyle = '#d4a44a';
          ctx.lineWidth = 5;
          ctx.beginPath();
          ctx.moveTo(
            cue.x + RAIL - nx * stickStart,
            cue.y + RAIL - ny * stickStart
          );
          ctx.lineTo(
            cue.x + RAIL - nx * (stickStart + stickLen),
            cue.y + RAIL - ny * (stickStart + stickLen)
          );
          ctx.stroke();

          // Cue tip
          ctx.strokeStyle = '#f0e0b0';
          ctx.lineWidth = 4;
          ctx.beginPath();
          ctx.moveTo(
            cue.x + RAIL - nx * stickStart,
            cue.y + RAIL - ny * stickStart
          );
          ctx.lineTo(
            cue.x + RAIL - nx * (stickStart + 8),
            cue.y + RAIL - ny * (stickStart + 8)
          );
          ctx.stroke();

          // Power bar
          ctx.fillStyle = 'rgba(0,0,0,0.5)';
          ctx.fillRect(RAIL + W - 120, RAIL + H - 25, 104, 14);
          const barColor = power < 0.5 ? '#4a4' : power < 0.8 ? '#da4' : '#d44';
          ctx.fillStyle = barColor;
          ctx.fillRect(RAIL + W - 118, RAIL + H - 23, power * 100, 10);
          ctx.strokeStyle = '#fff';
          ctx.lineWidth = 1;
          ctx.strokeRect(RAIL + W - 120, RAIL + H - 25, 104, 14);
        }
      }
    }
  }

  function drawBall(b, index) {
    const bx = b.x + RAIL;
    const by = b.y + RAIL;
    const num = b.number !== undefined ? b.number : index;

    // Shadow
    ctx.beginPath();
    ctx.arc(bx + 2, by + 2, R, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.fill();

    // Ball body
    ctx.beginPath();
    ctx.arc(bx, by, R, 0, Math.PI * 2);

    if (b.cue) {
      // Cue ball - white
      ctx.fillStyle = '#f8f8f8';
      ctx.fill();
    } else if (num >= 9 && num <= 15) {
      // Stripe ball
      ctx.fillStyle = '#f8f8f8';
      ctx.fill();
      // Color stripe
      ctx.save();
      ctx.beginPath();
      ctx.arc(bx, by, R, 0, Math.PI * 2);
      ctx.clip();
      ctx.fillStyle = ballColors[num];
      ctx.fillRect(bx - R, by - R * 0.5, R * 2, R);
      ctx.restore();
    } else {
      // Solid ball
      ctx.fillStyle = ballColors[num];
      ctx.fill();
    }

    // Number circle (for numbered balls)
    if (!b.cue && num > 0) {
      ctx.beginPath();
      ctx.arc(bx, by, R * 0.45, 0, Math.PI * 2);
      ctx.fillStyle = '#fff';
      ctx.fill();
      ctx.fillStyle = '#000';
      ctx.font = `bold ${R * 0.7}px Arial`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(num.toString(), bx, by + 0.5);
    }

    // Highlight/shine
    ctx.beginPath();
    ctx.arc(bx - R * 0.3, by - R * 0.3, R * 0.3, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255,255,255,0.35)';
    ctx.fill();

    // Border
    ctx.beginPath();
    ctx.arc(bx, by, R, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(0,0,0,0.3)';
    ctx.lineWidth = 0.5;
    ctx.stroke();
  }

  // Mouse handling
  function getCanvasPos(e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX - RAIL,
      y: (e.clientY - rect.top) * scaleY - RAIL
    };
  }

  canvas.addEventListener('mousedown', function(e) {
    const pos = getCanvasPos(e);
    const cue = getCueBall();
    if (!cue || cue.potted) return;

    const dx = pos.x - cue.x;
    const dy = pos.y - cue.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist < R * 3) {
      aiming = true;
      aimStart = { x: cue.x, y: cue.y };
      aimCurrent = { x: pos.x, y: pos.y };
    }
  });

  canvas.addEventListener('mousemove', function(e) {
    if (!aiming) return;
    aimCurrent = getCanvasPos(e);
    if (!paused) draw();
  });

  canvas.addEventListener('mouseup', function(e) {
    if (!aiming) return;
    aiming = false;

    const cue = getCueBall();
    if (!cue || cue.potted) return;

    const dx = aimStart.x - aimCurrent.x;
    const dy = aimStart.y - aimCurrent.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist > 5) {
      const power = Math.min(dist / MAX_DRAG, 1);
      const speed = power * MAX_POWER;
      const nx = dx / dist;
      const ny = dy / dist;

      cue.vx = nx * speed;
      cue.vy = ny * speed;
    }

    if (!paused) draw();
  });

  // Touch support
  canvas.addEventListener('touchstart', function(e) {
    e.preventDefault();
    const touch = e.touches[0];
    const mouseEvent = new MouseEvent('mousedown', {
      clientX: touch.clientX,
      clientY: touch.clientY
    });
    canvas.dispatchEvent(mouseEvent);
  });

  canvas.addEventListener('touchmove', function(e) {
    e.preventDefault();
    const touch = e.touches[0];
    const mouseEvent = new MouseEvent('mousemove', {
      clientX: touch.clientX,
      clientY: touch.clientY
    });
    canvas.dispatchEvent(mouseEvent);
  });

  canvas.addEventListener('touchend', function(e) {
    e.preventDefault();
    const mouseEvent = new MouseEvent('mouseup', {});
    canvas.dispatchEvent(mouseEvent);
  });

  // Reset button
  document.getElementById('resetBtn').addEventListener('click', function() {
    const defaultBalls = createDefaultBalls();
    sim.reset(defaultBalls);
    if (!paused) draw();
    updateStatus();
  });

  function updateStatus() {
    const potted = balls.filter(b => b.potted && !b.cue).length;
    const total = balls.filter(b => !b.cue).length;
    document.getElementById('status').textContent =
      `Balls potted: ${potted} / ${total}`;
  }

  // Game loop
  function gameLoop(timestamp) {
    if (paused) return;

    if (lastTime === 0) lastTime = timestamp;
    let dt = (timestamp - lastTime) / 1000;
    lastTime = timestamp;

    if (dt > 0.05) dt = 0.05;

    sim.step(dt);
    updateStatus();

    animId = requestAnimationFrame(gameLoop);
  }

  // Initialize
  const defaultBalls = createDefaultBalls();
  sim.reset(defaultBalls);
  draw();
  updateStatus();

  lastTime = 0;
  animId = requestAnimationFrame(gameLoop);
})();
</script>
</body>
</html>
